before:
Complete local Kotlin/JVM example; the app itself does not execute it:
```kotlin
interface Formatter { fun format(text: String): String }
class Plain : Formatter {
    override fun format(text: String): String = text
}
class Marked : Formatter {
    override fun format(text: String): String = "[$text]"
}
fun show(formatter: Formatter) { println(formatter.format("C")) }
fun main() { show(Plain()) }
```

